SELECT p.gender, p.anchor_year, a.admission_type_id, a.discharge_to, s.stay_length, s.discharge_disposition, percent_rank() OVER (PARTITION BY p.gender, p.anchor_year, a.discharge_to, s.stay_length ORDER BY s.discharge_disposition) AS percentile_rank FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays s ON a.stay_id = s.stay_id WHERE p.gender = 'M' AND p.anchor_year BETWEEN 86 AND 96 AND a.admission_type_id = 1 AND s.discharge_disposition IN ('home', 'facility', 'in‑hospital death') AND s.stay_length BETWEEN 10 AND 30 ORDER BY p.gender, p.anchor_year, a.discharge_to, s.stay_length, s.discharge_disposition NULLS LAST;